function notifyCrud(action, subject) {
  const messages = {
    created: `${subject} creado correctamente.`,
    updated: `${subject} actualizado correctamente.`,
    deleted: `${subject} eliminado correctamente.`,
    saved: `${subject} guardado correctamente.`
  };
  toast.success(messages[action] || `${subject} realizado correctamente.`);
}

function ProgressRing({ value, size = 112, stroke = 9, color = '#42d6a4', children }) {
  const radius = (size - stroke) / 2; const circumference = 2 * Math.PI * radius;
  const reduceMotion = useReducedMotion();
  return <div className="progress-ring" style={{ width: size, height: size }}>
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
      <circle className="ring-track" cx={size/2} cy={size/2} r={radius} strokeWidth={stroke}/>
      <motion.circle initial={reduceMotion ? false : { strokeDashoffset: circumference }} animate={{ strokeDashoffset: circumference - value / 100 * circumference }} transition={reduceMotion ? { duration: 0 } : { duration: 1.2, ease: 'easeOut' }} className="ring-value" cx={size/2} cy={size/2} r={radius} strokeWidth={stroke} stroke={color} strokeDasharray={circumference} strokeLinecap="round"/>
    </svg><div className="ring-center">{children}</div>
  </div>;
}

function AnimatedNumber({ value, suffix = '' }) { const reduceMotion = useReducedMotion(); return <motion.span initial={reduceMotion ? false : { opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={reduceMotion ? { duration: 0 } : { delay: .25 }}>{value}{suffix}</motion.span>; }

