function Register() {
  const navigate = useNavigate(); const [step, setStep] = useState(1); const [selected, setSelected] = useState(['smoking']); const [goal, setGoal] = useState('Reducir');
  const next = () => step < 4 ? setStep(step + 1) : navigate('/app');
  return <main className="wizard-page page-dark"><div className="wizard-shell"><div className="wizard-header"><Logo/><span className="step-label">Paso {step} de 4</span><button className="close-wizard" onClick={() => navigate('/welcome')}><X size={20}/></button></div><div className="wizard-progress"><motion.div animate={{ width: `${step * 25}%` }}/></div><AnimatePresence mode="wait"><motion.div key={step} className="wizard-content" initial={{ opacity: 0, x: 15 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -15 }} transition={{ duration: .25 }}>
    {step === 1 && <><div className="eyebrow">EMPECEMOS POR TI</div><h1>¿Cómo quieres<br/><em>empezar?</em></h1><p className="wizard-intro">Solo necesitamos unos datos para personalizar tu experiencia.</p><div className="form-grid"><label>Tu nombre<input placeholder="¿Cómo te llamamos?" /></label><label>Email<input type="email" placeholder="tu@email.com" /></label><label>Contraseña<input type="password" placeholder="Mínimo 8 caracteres" /></label><label>Confirmar contraseña<input type="password" placeholder="Repite tu contraseña" /></label></div></>}
    {step === 2 && <><div className="eyebrow">TU PUNTO DE PARTIDA</div><h1>¿Qué quieres<br/><em>mejorar?</em></h1><p className="wizard-intro">Elige todo lo que aplique. No hay respuestas correctas.</p><div className="habit-grid">{habits.map(({ id, label, icon: Icon }) => <button key={id} className={`habit-choice ${selected.includes(id) ? 'selected' : ''}`} onClick={() => setSelected(selected.includes(id) ? selected.filter(x => x !== id) : [...selected, id])}><span className="habit-icon"><Icon size={20}/></span><span>{label}</span>{selected.includes(id) && <motion.span initial={{ scale: 0 }} animate={{ scale: 1 }} className="choice-check"><Check size={13}/></motion.span>}</button>)}</div></>}
    {step === 3 && <><div className="eyebrow">UN OBJETIVO A TU MEDIDA</div><h1>¿Qué quieres<br/><em>lograr?</em></h1><p className="wizard-intro">Para <b>{selected[0] === 'smoking' ? 'cigarrillo' : 'tu hábito'}</b>, elige el objetivo que te haga sentido.</p><div className="option-stack">{['Dejar completamente','Reducir','Controlar frecuencia'].map(x => <button key={x} className={`wide-choice ${goal === x ? 'selected' : ''}`} onClick={() => setGoal(x)}><span><b>{x}</b><small>{x === 'Dejar completamente' ? 'Cero días, un paso a la vez' : x === 'Reducir' ? 'Menos, con intención' : 'Tú decides el ritmo'}</small></span>{goal === x ? <Check size={18}/> : <ChevronRight size={18}/>}</button>)}</div><label className="money-label">¿Cuánto gastas aproximadamente?<div className="money-input"><span>$</span><input placeholder="0" inputMode="decimal"/><select><option>por semana</option><option>por día</option><option>por mes</option></select></div></label></>}
    {step === 4 && <><div className="eyebrow">TU MOTIVACIÓN</div><h1>¿Por qué quieres<br/><em>cambiar?</em></h1><p className="wizard-intro">Tu razón será tu ancla en los días difíciles.</p><div className="reason-grid">{['Salud','Dinero','Familia','Productividad','Disciplina','Bienestar'].map((x,i) => <button type="button" key={x} className={`reason-choice ${i === 0 ? 'selected' : ''}`}><span>{React.createElement([HeartPulse, CircleDollarSign, Users, Rocket, Target, Sparkles][i], { size: 20 })}</span>{x}</button>)}</div><p className="goal-label">Define tu primera meta</p><div className="goal-pills">{['3 días','7 días','14 días','30 días','90 días'].map((x,i) => <button type="button" className={i === 1 ? 'selected' : ''} key={x}>{x}</button>)}</div></>}
  </motion.div></AnimatePresence><div className="wizard-footer"><button className="text-button" onClick={() => step > 1 ? setStep(step - 1) : navigate('/welcome')}>← Atrás</button><Button onClick={next}>{step === 4 ? 'Crear mi plan' : 'Continuar'} <ArrowRight size={18}/></Button></div></div></main>;
}

function AuthConnected() {
  const navigate = useNavigate(); const [form, setForm] = useState({ email: '', password: '' }); const [error, setError] = useState(''); const [loading, setLoading] = useState(false); const [showPassword, setShowPassword] = useState(false);
  const submit = async (event) => { event.preventDefault(); setError(''); setLoading(true); const result = await dataApi.authService.signIn(form.email, form.password); if (result.error) { setLoading(false); setError(result.error.message || 'No pudimos iniciar sesión.'); return; } try { await dataApi.onboardingService.completePending(); } catch (completionError) { setError(completionError.message || 'No pudimos terminar de configurar tu plan.'); } setLoading(false); navigate('/app'); };
  return <main className="auth-page page-dark"><div className="auth-panel"><Logo/><button className="back-button" onClick={() => navigate('/welcome')}>← Volver</button><div className="auth-content"><div className="eyebrow">BIENVENIDO DE VUELTA</div><h1>Tu progreso<br/><em>te espera.</em></h1><p>Continúa construyendo la versión de ti que quieres ver.</p><form onSubmit={submit}><label>Email<input type="email" value={form.email} onChange={e => setForm({ ...form, email: e.target.value })} placeholder="tu@email.com" required /></label><label>Contraseña<div className="input-wrap"><input type={showPassword ? 'text' : 'password'} value={form.password} onChange={e => setForm({ ...form, password: e.target.value })} placeholder="••••••••" required /><button type="button" onClick={() => setShowPassword(!showPassword)}>{showPassword ? 'Ocultar' : 'Mostrar'}</button></div></label>{error && <p className="form-error">{error}</p>}<Button className="full-button" disabled={loading}>{loading ? 'Entrando…' : 'Iniciar sesión'} <ArrowRight size={18}/></Button></form><p className="auth-bottom">¿Aún no tienes cuenta? <button className="text-button" onClick={() => navigate('/register')}>Crear una</button></p></div></div><div className="auth-aside"><div className="aside-quote">“Cada día que eliges<br/><em>seguir, cuenta.</em>”</div><div className="aside-stats"><span><b>12</b><small>días en control</small></span><span><b>91%</b><small>cumplimiento</small></span></div></div></main>;
}

