function NotificationsPage() {
  const navigate = useNavigate();
  const [settings, setSettings] = useState({});
  const [notifications, setNotifications] = useState([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState('');
  useEffect(() => {
    let mounted = true;
    Promise.allSettled([dataApi.notificationService.get(), dataApi.notificationService.list()])
      .then(([preferences, inbox]) => {
        if (!mounted) return;
        if (preferences.status === 'fulfilled') setSettings(preferences.value || {});
        if (inbox.status === 'fulfilled') setNotifications(inbox.value || []);
      })
      .finally(() => { if (mounted) setLoading(false); });
    return () => { mounted = false; };
  }, []);
  const openNotification = async item => {
    if (!item.read_at) {
      await dataApi.notificationService.markRead(item.id).catch(() => {});
      setNotifications(current => current.map(notification => notification.id === item.id ? { ...notification, read_at: new Date().toISOString() } : notification));
    }
    if (item.action_path) navigate(item.action_path);
  };
  const toggle = async key => {
    const previous = Boolean(settings[key]);
    const value = !previous;
    setSettings(current => ({ ...current, [key]: value }));
    setSaving(key);
    try {
      await dataApi.notificationService.update({ [key]: value });
    } catch (error) {
      setSettings(current => ({ ...current, [key]: previous }));
      toast.error(error.message || 'No pudimos actualizar las notificaciones.');
    } finally {
      setSaving('');
    }
  };
  const unreadCount = notifications.filter(item => !item.read_at).length;
  return <div className="notifications-page"><div className="page-intro notifications-intro"><div><span className="eyebrow">TU ACOMPAÑAMIENTO</span><h1>Notificaciones</h1><p>Elige qué señales quieres recibir sobre tu proceso.</p></div><div className="notifications-hero-icon surface-card" aria-hidden="true"><Bell size={24}/></div></div><section className="notification-inbox surface-card" aria-busy={loading}><div className="notifications-panel-heading"><div><span className="card-kicker">TU ACTIVIDAD</span><h2>Todo lo que necesitas saber</h2></div>{unreadCount > 0 && <span className="notification-count">{unreadCount} nuevas</span>}</div>{loading ? <p className="notifications-status">Cargando tus notificaciones…</p> : notifications.length ? <div className="notification-list">{notifications.map(item => { const Icon = item.notification_type === 'feed' ? Newspaper : Bell; return <button type="button" className={`notification-item ${item.read_at ? '' : 'is-unread'}`} key={item.id} onClick={() => openNotification(item)}><span className="notification-item-icon"><Icon size={17}/></span><span className="notification-item-copy"><b>{item.title}</b><small>{item.body}</small><time>{item.created_at ? new Intl.DateTimeFormat('es-CO', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(item.created_at)) : ''}</time></span>{!item.read_at && <i className="notification-unread-dot" aria-label="No leída"/>}</button>; })}</div> : <p className="notifications-empty">Aún no tienes notificaciones. Tu próxima sesión aparecerá aquí.</p>}</section><section className="notifications-panel surface-card" aria-busy={loading}><div className="notifications-panel-heading"><span className="card-kicker">PREFERENCIAS</span><h2>Señales que te acompañan</h2></div>{loading ? <p className="notifications-status">Cargando tus preferencias…</p> : notificationOptions.map(({ key, label, description, icon: Icon }) => <label className="notification-row" key={key}><span className="notification-row-icon"><Icon size={18}/></span><span className="notification-copy"><b>{label}</b><small>{description}</small></span><input type="checkbox" checked={Boolean(settings[key])} disabled={saving === key} onChange={() => toggle(key)} /></label>)}</section></div>;
}

function NotificationBell() {
  const navigate = useNavigate();
  const [unreadCount, setUnreadCount] = useState(0);
  useEffect(() => {
    let mounted = true;
    const loadCount = () => dataApi.notificationService.unreadCount().then(count => { if (mounted) setUnreadCount(count); }).catch(() => {});
    loadCount();
    window.addEventListener('sophena:notifications-updated', loadCount);
    return () => { mounted = false; window.removeEventListener('sophena:notifications-updated', loadCount); };
  }, []);
  const label = unreadCount ? `Notificaciones, ${unreadCount} sin leer` : 'Notificaciones';
  return <button className="notification-button" aria-label={label} onClick={() => navigate('/app/notifications')}><Bell size={19}/>{unreadCount > 0 && <span className="notification-badge" aria-live="polite">{unreadCount > 99 ? '99+' : unreadCount}</span>}</button>;
}

