function SuperAdminShellV2() {
  const navigate = useNavigate();
  const [authorized, setAuthorized] = useState(() => sessionStorage.getItem('sophena-super-admin-authenticated') === 'true');
  const [checking, setChecking] = useState(() => sessionStorage.getItem('sophena-super-admin-authenticated') === 'true');
  useEffect(() => {
    if (!authorized) { setChecking(false); return undefined; }
    let active = true;
    dataApi.profileService.get().then(profile => {
      if (active && profile?.role !== 'super_admin') {
        sessionStorage.removeItem('sophena-super-admin-authenticated');
        setAuthorized(false);
      }
    }).catch(() => {
      if (active) { sessionStorage.removeItem('sophena-super-admin-authenticated'); setAuthorized(false); }
    }).finally(() => { if (active) setChecking(false); });
    return () => { active = false; };
  }, [authorized]);
  if (checking) return <main className="page-dark admin-loading">Validando acceso administrativo...</main>;
  return authorized ? <SuperAdminPanel/> : <SuperAdminLogin onSuccess={() => { sessionStorage.setItem('sophena-super-admin-authenticated', 'true'); setAuthorized(true); navigate('/super-admin'); }}/>;
}

function SuperAdminLogin({ onSuccess }) {
  const navigate = useNavigate();
  const [form, setForm] = useState({ email: '', password: '' });
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const submit = async event => {
    event.preventDefault();
    setLoading(true);
    setError('');
    const result = await dataApi.authService.signIn(form.email.trim(), form.password);
    if (result.error) {
      setLoading(false);
      setError('Las credenciales no son válidas.');
      return;
    }
    try {
      const profile = await dataApi.profileService.get();
      if (profile?.role !== 'super_admin') {
        await dataApi.authService.signOut();
        setError('Esta cuenta no tiene permisos de super administrador.');
        setLoading(false);
        return;
      }
      onSuccess();
    } catch {
      await dataApi.authService.signOut();
      setError('No pudimos validar los permisos de esta cuenta.');
    } finally {
      setLoading(false);
    }
  };

  return <main className="page-dark admin-auth-page"><div className="admin-auth-card surface-card"><div className="admin-auth-brand"><Logo/><span className="admin-badge"><ShieldCheck size={14}/> SUPER ADMIN</span></div><div className="admin-auth-icon"><ShieldCheck size={27}/></div><span className="eyebrow">ACCESO PRIVILEGIADO</span><h1>Entra al panel<br/><em>de SOPHENA.</em></h1><p>Confirma las credenciales de tu cuenta administradora para continuar.</p><form onSubmit={submit}><label>Correo del administrador<input type="email" value={form.email} onChange={event => setForm({ ...form, email: event.target.value })} placeholder="admin@sophena.online" autoComplete="username" required /></label><label>Contraseña<div className="admin-password-field"><input type={showPassword ? 'text' : 'password'} value={form.password} onChange={event => setForm({ ...form, password: event.target.value })} placeholder="Tu contraseña" autoComplete="current-password" required /><button type="button" onClick={() => setShowPassword(current => !current)} aria-label={showPassword ? 'Ocultar contraseña' : 'Mostrar contraseña'}>{showPassword ? <EyeOff size={17}/> : <Eye size={17}/>}</button></div></label>{error && <p className="form-error">{error}</p>}<Button className="full-button" disabled={loading}>{loading ? 'Verificando...' : 'Entrar al panel'} <ArrowRight size={17}/></Button></form><button type="button" className="admin-forgot-link" onClick={() => navigate('/forgot-password')}>¿Olvidaste tu contraseña?</button><button className="admin-auth-back text-button" onClick={() => navigate('/login')}><ArrowRight size={15} style={{ transform: 'rotate(180deg)' }}/> Volver al inicio de sesión</button><small className="admin-auth-note"><LockKeyhole size={13}/> Acceso protegido por Supabase Auth</small></div></main>;
}

