function money(value) { return new Intl.NumberFormat('es-CO', { style: 'currency', currency: 'COP', maximumFractionDigits: 0 }).format(Number(value || 0)); }
function initials(name = '') { return name.split(' ').filter(Boolean).slice(0, 2).map(part => part[0]).join('').toUpperCase() || 'NU'; }
function browserDateKey(value = new Date()) {
  if (typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value)) return value;
  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) return '';
  const pad = number => String(number).padStart(2, '0');
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
}
function streakFromCheckins(checkins) {
  const dates = new Set(checkins.filter(item => item.status === 'completed').map(item => item.checkin_date || browserDateKey(item.created_at)));
  let cursor = new Date(); let streak = 0;
  while (dates.has(browserDateKey(cursor))) { streak += 1; cursor.setDate(cursor.getDate() - 1); }
  return streak;
}

function DashboardConnected({ openSheet }) {
  const navigate = useNavigate(); const [state, setState] = useState({ profile: null, checkins: [], cravings: [], savings: [], habits: [] }); const [loading, setLoading] = useState(true);
  useEffect(() => { Promise.allSettled([dataApi.profileService.get(), dataApi.checkinService.list(), dataApi.cravingService.list(), dataApi.savingService.list(), dataApi.habitService.list()]).then(([profile, checkins, cravings, savings, habits]) => setState({ profile: profile.status === 'fulfilled' ? profile.value : null, checkins: checkins.status === 'fulfilled' ? checkins.value : [], cravings: cravings.status === 'fulfilled' ? cravings.value : [], savings: savings.status === 'fulfilled' ? savings.value : [], habits: habits.status === 'fulfilled' ? habits.value : [] })).finally(() => setLoading(false)); }, []);
  const totalSaved = state.savings.reduce((total, item) => total + Number(item.amount || 0), 0); const streak = streakFromCheckins(state.checkins); const completed = state.checkins.filter(item => item.status === 'completed').length; const compliance = state.checkins.length ? Math.round((completed / state.checkins.length) * 100) : 0; const target = 7; const progress = Math.min(100, Math.round((streak / target) * 100)); const days = Array.from({ length: 7 }, (_, index) => { const date = new Date(); date.setDate(date.getDate() - (6 - index)); const iso = browserDateKey(date); return { day: date.toLocaleDateString('es-CO', { weekday: 'short' }).replace('.', '').slice(0, 3), value: state.checkins.some(item => (item.checkin_date || browserDateKey(item.created_at)) === iso && item.status === 'completed') ? 100 : 0 }; });
  return <div className="dashboard"><div className="mobile-page-title"><span className="eyebrow">TU ESPACIO PERSONAL</span><h1>Hola, {state.profile?.full_name || 'ahí'} <span>✦</span></h1><p>{loading ? 'Cargando tus datos…' : 'Así vas hoy. Un día a la vez.'}</p></div><div className="dashboard-grid"><motion.section className="streak-card surface-card"><div className="streak-top"><div><span className="card-kicker"><span className="pulse-dot"/> RACHA ACTUAL</span><h3><AnimatedNumber value={String(streak)}/> <small>días</small></h3><p>{state.habits[0]?.name || 'tu hábito'}</p></div><ProgressRing value={progress} size={128} color="#42d6a4"><b>{progress}<small>%</small></b><span>del objetivo</span></ProgressRing></div><div className="streak-divider"/><div className="streak-bottom"><div><small>Próximo objetivo</small><b>{target} días</b></div><div className="days-left"><strong>{Math.max(0, target - streak)}</strong><span>faltan</span></div><button className="circle-arrow" onClick={() => navigate('/app/progress')}><ArrowRight size={17}/></button></div></motion.section><section className="motivation-card surface-card"><div className="motivation-bg"/><Sparkles className="motivation-spark" size={20}/><span className="card-kicker">RECUERDA</span><h3>Cada registro<br/><em>cuenta.</em></h3><p>Haz visible el avance, incluso cuando el día no salga perfecto.</p><div className="motivation-author"><span>✦</span> SOPHENA para ti</div></section></div><div className="section-heading"><div><span className="eyebrow">DATOS REALES</span><h3>Tu resumen</h3></div><button className="text-button" onClick={() => navigate('/app/progress')}>Ver progreso <ArrowRight size={15}/></button></div><div className="stats-grid"><StatCard icon={Wallet} label="Dinero recuperado" value={money(totalSaved)} detail={`${state.savings.length} registros de ahorro`} tone="green"/><StatCard icon={ShieldCheck} label="Impulsos superados" value={String(state.cravings.filter(item => item.outcome !== 'no').length)} detail={`${state.cravings.length} impulsos registrados`} tone="purple"/><StatCard icon={Trophy} label="Hábitos activos" value={String(state.habits.filter(item => item.active !== false).length)} detail="Configurados en tu plan" tone="amber"/><StatCard icon={Target} label="Cumplimiento" value={`${compliance}%`} detail={`${completed} check-ins guardados`} tone="blue" ring={compliance}/></div><section className="checkin-card surface-card"><div className="checkin-icon"><CalendarDays size={21}/></div><div><span className="card-kicker">CHECK-IN DE HOY</span><h3>¿Cómo te fue hoy?</h3><p>Registrar cómo te sientes toma menos de un minuto.</p></div><Button variant="secondary" onClick={openSheet}>Registrar <ArrowRight size={16}/></Button></section><div className="section-heading"><div><span className="eyebrow">TU ACTIVIDAD</span><h3>Últimos 7 días</h3></div><div className="chart-legend"><i/> Cumplimiento</div></div><section className="chart-card surface-card"><div className="chart-summary"><div><b>{compliance}%</b><span>cumplimiento registrado</span></div><span className="trend-up">{state.checkins.length ? 'Datos sincronizados' : 'Aún sin registros'}</span></div><div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><AreaChart data={days} margin={{ top: 10, right: 0, left: -30, bottom: 0 }}><defs><linearGradient id="chartFillConnected" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#7c5cff" stopOpacity=".35"/><stop offset="100%" stopColor="#7c5cff" stopOpacity="0"/></linearGradient></defs><CartesianGrid vertical={false} stroke="rgba(255,255,255,.06)"/><XAxis dataKey="day" axisLine={false} tickLine={false} tick={{ fill: '#697181', fontSize: 11 }}/><YAxis hide domain={[0,100]}/><Tooltip contentStyle={{ background: '#202632', border: '1px solid rgba(255,255,255,.1)', borderRadius: 12, color: '#fff' }}/><Area type="monotone" dataKey="value" stroke="#8d75ff" strokeWidth={3} fill="url(#chartFillConnected)" dot={{ fill: '#8d75ff', strokeWidth: 0, r: 3 }} activeDot={{ r: 5, fill: '#42d6a4' }}/></AreaChart></ResponsiveContainer></div></section></div>;
}

