function ProfilePageStaticLegacy() { return <div className="profile-page"><div className="profile-hero surface-card"><div className="profile-avatar">CM<span><Check size={11}/></span></div><div><span className="eyebrow">TU PERFIL</span><h1>Camila Martínez</h1><p>Exploradora · Miembro desde septiembre 2024</p></div><button className="icon-button"><Settings size={18}/></button></div><div className="profile-layout"><section><div className="section-heading"><div><span className="eyebrow">TU INFORMACIÓN</span><h3>Cuenta</h3></div></div><div className="settings-list surface-card"><SettingRow icon={UserRound} label="Datos personales" value="Camila Martínez"/><SettingRow icon={Target} label="Hábitos y objetivos" value="1 hábito activo"/><SettingRow icon={Bell} label="Notificaciones" value="Activas"/><SettingRow icon={Sparkles} label="Apariencia" value="Oscuro"/><SettingRow icon={ShieldCheck} label="Privacidad" value="Tus datos son tuyos"/></div><button className="logout-button"><LogOut size={17}/> Cerrar sesión</button></section><section className="profile-side"><div className="section-heading"><div><span className="eyebrow">TU IMPACTO</span><h3>Desde que empezaste</h3></div></div><div className="impact-card surface-card"><div><Wallet size={19}/><b>$428.000</b><span>dinero recuperado</span></div><div><Flame size={19}/><b>38 días</b><span>mejor racha</span></div><div><ShieldCheck size={19}/><b>18</b><span>impulsos superados</span></div></div></section></div></div>; }
function ProgressPage() {
  const [data, setData] = useState({ checkins: [], cravings: [], savings: [], loading: true });
  useEffect(() => {
    const refresh = () => Promise.allSettled([dataApi.checkinService.list(), dataApi.cravingService.list(), dataApi.savingService.list()]).then(([checkins, cravings, savings]) => setData({ checkins: checkins.value || [], cravings: cravings.value || [], savings: savings.value || [], loading: false }));
    refresh();
    window.addEventListener('sophena:record-created', refresh);
    return () => window.removeEventListener('sophena:record-created', refresh);
  }, []);
  const today = new Date(); const days = Array.from({ length: 30 }, (_, index) => { const date = new Date(today); date.setHours(12, 0, 0, 0); date.setDate(today.getDate() - (29 - index)); return date; });
  const key = browserDateKey; const completed = new Set(data.checkins.filter(item => item.status === 'completed').map(item => item.checkin_date || key(item.created_at))); const risks = new Set(data.cravings.map(item => key(item.created_at))); const completedLast30 = days.filter(day => completed.has(key(day))).length; const compliance = Math.round((completedLast30 / 30) * 100); const saved = data.savings.reduce((total, item) => total + Number(item.amount || 0), 0); const weekly = Array.from({ length: 7 }, (_, index) => { const day = new Date(today); day.setHours(12, 0, 0, 0); day.setDate(today.getDate() - (6 - index)); const dayKey = key(day); return { day: day.toLocaleDateString('es-CO', { weekday: 'short' }).replace('.', '').slice(0, 1).toUpperCase(), value: completed.has(dayKey) ? 100 : 0 }; });
  const mainTrigger = data.cravings.reduce((result, item) => { result[item.trigger || 'Otro'] = (result[item.trigger || 'Otro'] || 0) + 1; return result; }, {}); const trigger = Object.entries(mainTrigger).sort((a, b) => b[1] - a[1])[0]?.[0];
  return <div className="progress-page"><div className="page-intro"><div><span className="eyebrow">VISTA GENERAL</span><h1>Tu progreso, <em>visible.</em></h1><p>{data.loading ? 'Cargando tus registros...' : 'Cada registro refleja tu proceso real.'}</p></div><div className="progress-total"><ProgressRing value={compliance} size={88} stroke={7} color="#7c5cff"><b>{compliance}<small>%</small></b></ProgressRing></div></div><div className="progress-layout"><section className="calendar-card surface-card"><div className="card-heading"><div><span className="card-kicker">ÚLTIMOS 30 DÍAS</span><h3>Tu constancia</h3></div><span className="calendar-live">Datos reales</span></div><div className="weekday-row">{['L','M','X','J','V','S','D'].map(x => <span key={x}>{x}</span>)}</div><div className="calendar-grid">{days.map(day => { const dayKey = key(day); const isComplete = completed.has(dayKey); const isRisk = risks.has(dayKey); return <div key={dayKey} className={`calendar-day ${isComplete ? 'success-day' : isRisk ? 'risk-day' : 'neutral-day'} ${dayKey === key(today) ? 'today' : ''}`}><span>{day.getDate()}</span>{(isComplete || isRisk) && <i/>}</div>; })}</div><div className="calendar-legend"><span><i className="legend-success"/> Objetivo cumplido</span><span><i className="legend-risk"/> Impulso registrado</span><span><i className="legend-neutral"/> Sin registro</span></div></section><section className="progress-summary"><div className="summary-highlight surface-card"><span className="card-kicker">CUMPLIMIENTO REAL</span><div><strong>{completedLast30}</strong><span>/ 30 días</span></div><p>{completedLast30 ? 'Tu avance está tomando forma. Sigue a tu ritmo.' : 'Todavía no hay check-ins en este periodo.'}</p><div className="thin-progress"><i style={{ width: `${compliance}%` }}/></div></div><div className="weekly-card surface-card"><div className="card-heading"><div><span className="card-kicker">ESTA SEMANA</span><h3>{Math.round(weekly.reduce((sum, item) => sum + item.value, 0) / 7)}% cumplimiento</h3></div><span className="trend-up">{data.checkins.length} registros</span></div><div className="week-bars">{weekly.map((item, index) => <div key={`${item.day}-${index}`}><div className="bar-bg"><i style={{ height: `${Math.max(item.value, 7)}%` }}/></div><span>{item.day}</span></div>)}</div></div></section></div><div className="section-heading"><div><span className="eyebrow">LECTURAS CLAVE</span><h3>Lo que tus datos cuentan</h3></div></div><div className="insights-grid"><InsightCard icon={Clock3} text={trigger ? `Tu detonante más frecuente es ${trigger}.` : 'Registra impulsos para identificar tus detonantes.'}/><InsightCard icon={CalendarDays} text={`${completedLast30} de 30 días tienen un check-in completado.`}/><InsightCard icon={CircleDollarSign} text={saved ? `Has registrado ${money(saved)} de dinero evitado.` : 'Registra un gasto evitado para ver tu impacto económico.'}/></div></div>;
}

