function IntensitySlider({ value, onChange }) {
  const level = Number(value); const progress = `${((level - 1) / 9) * 100}%`; const tone = level <= 3 ? 'low' : level <= 6 ? 'medium' : 'high'; const label = level <= 3 ? 'Manejable' : level <= 6 ? 'Presente' : 'Intenso';
  return <div className="intensity-control"><div className="intensity-head"><span>Intensidad del impulso</span><strong>{level}/10</strong></div><input className={`intensity-range intensity-${tone}`} type="range" min="1" max="10" step="1" value={level} style={{ '--range-progress': progress }} onChange={e => onChange(Number(e.target.value))}/><div className="intensity-marks">{Array.from({ length: 10 }, (_, index) => <span className={index + 1 <= level ? 'active' : ''} key={index}>{index + 1}</span>)}</div><div className={`intensity-feedback intensity-feedback-${tone}`}><span className="intensity-dot"/><b>{label}</b><small>{tone === 'low' ? 'Puedes observarlo y dejarlo pasar.' : tone === 'medium' ? 'Respira. Todavía puedes elegir.' : 'Pausa. Estás a tiempo de pedir apoyo.'}</small></div></div>;
}

function ActionSheetConnected({ close }) {
  const [action, setAction] = useState('menu'); const [saving, setSaving] = useState(false); const [form, setForm] = useState({ intensity: 5, trigger: 'Estrés', outcome: 'mucho', amount: '', note: '' }); const [error, setError] = useState('');
  const actions = [{ id: 'checkin', label: 'Registrar día', hint: 'Marca tu avance', icon: Check, tone: 'green' }, { id: 'craving', label: 'Tengo un impulso', hint: 'Te acompañamos', icon: ShieldCheck, tone: 'purple' }, { id: 'relapse', label: 'Registrar recaída', hint: 'Sin juicios, seguimos', icon: HeartPulse, tone: 'pink' }, { id: 'saving', label: 'Gasto evitado', hint: 'Hazlo visible', icon: CircleDollarSign, tone: 'amber' }];
  const submit = async event => { event.preventDefault(); setSaving(true); setError(''); try { if (action === 'checkin') { const item = await dataApi.checkinService.create({ checkin_date: browserDateKey(), status: 'completed', note: form.note }); await dataApi.pointService.award({ actionKey: 'checkin_completed', sourceId: item.id }); } if (action === 'craving') { const item = await dataApi.cravingService.create({ intensity: Number(form.intensity), trigger: form.trigger, outcome: form.outcome, duration_minutes: 10 }); if (form.outcome === 'mucho') await dataApi.pointService.award({ actionKey: 'craving_overcome', sourceId: item.id }); if (form.outcome === 'un_poco') await dataApi.pointService.award({ actionKey: 'craving_reduced', sourceId: item.id }); } if (action === 'relapse') await dataApi.relapseService.create({ note: form.note, occurred_at: new Date().toISOString() }); if (action === 'saving') { const item = await dataApi.savingService.create({ amount: Number(form.amount || 0), category: 'avoided_spend', note: form.note, saved_at: browserDateKey() }); await dataApi.pointService.award({ actionKey: 'saving_registered', sourceId: item.id, amount: item.amount }); await dataApi.pointService.award({ actionKey: 'saving_bonus', sourceId: item.id, amount: item.amount }); } await dataApi.userAchievementService.evaluate(); window.dispatchEvent(new Event('sophena:record-created')); notifyCrud('created', 'Registro'); close(); } catch (serviceError) { setError(serviceError.message || 'No pudimos guardar el registro.'); setSaving(false); } };
  return <div className="sheet-backdrop" onClick={close}><motion.div className="action-sheet action-sheet-modern" initial={{ y: 40, opacity: 0 }} animate={{ y: 0, opacity: 1 }} onClick={e => e.stopPropagation()}><div className="sheet-handle"/>{action === 'menu' ? <><div className="sheet-header"><div><span className="eyebrow">REGISTRO RÁPIDO</span><h2>Un momento para ti.</h2></div><button className="icon-button" onClick={close}><X size={19}/></button></div><div className="action-grid">{actions.map(({ id, label, hint, icon: Icon, tone }) => <button key={id} onClick={() => setAction(id)}><span className={`action-icon ${tone}`}><Icon size={21}/></span><b>{label}</b><small>{hint}</small></button>)}</div></> : <form onSubmit={submit}><div className="sheet-header"><div><span className="eyebrow">{actions.find(item => item.id === action)?.label.toUpperCase()}</span><h2>{action === 'craving' ? 'Bajemos la intensidad.' : 'Guarda este momento.'}</h2></div><button type="button" className="icon-button" onClick={() => setAction('menu')}><ArrowRight size={18} style={{ transform: 'rotate(180deg)' }}/></button></div>{action === 'craving' && <><div className="sheet-field intensity-field"><IntensitySlider value={form.intensity} onChange={intensity => setForm({ ...form, intensity })}/></div><label className="sheet-field">¿Qué lo detonó?<select value={form.trigger} onChange={e => setForm({ ...form, trigger: e.target.value })}>{['Estrés','Ansiedad','Aburrimiento','Amigos','Trabajo','Soledad','Otro'].map(item => <option key={item}>{item}</option>)}</select></label><label className="sheet-field">¿El impulso bajó?<select value={form.outcome} onChange={e => setForm({ ...form, outcome: e.target.value })}><option value="mucho">Mucho</option><option value="un_poco">Un poco</option><option value="no">No</option></select></label></>}{action === 'saving' && <label className="sheet-field">¿Cuánto evitaste gastar?<input type="number" min="0" value={form.amount} onChange={e => setForm({ ...form, amount: e.target.value })} placeholder="$ 0" required /></label>}<label className="sheet-field">Nota opcional<textarea value={form.note} onChange={e => setForm({ ...form, note: e.target.value })} placeholder="¿Cómo te fue?" rows="3"/></label>{error && <p className="form-error">{error}</p>}<Button className="full-button" disabled={saving}>{saving ? 'Guardando…' : 'Guardar registro'} <Check size={17}/></Button></form>}</motion.div></div>;
}

